(f) void mm_jki_roll(f64* A, f64* B, f64* C,

int RA, int CA, int CB) {

    for (int j0 = 0; j0 < CB; j0++) {

        for (int k0 = 0; k0 < CA; k0++) {

            for (int i0 = 0; i0 < RA; i0 += 2) {

                int ij = i0 * CB + j0;

                int ik = i0 * CA + k0;

                int kj = k0 * CB + j0;

                C[ij] += A[ik] * B[kj];

                ij = (i0+1) * CB + j0;

                ik = (i0+1) * CA + k0;

                kj = k0 * CB + j0;

                C[ij] += A[ik] * B[kj];

